var inorderSuccessor = function(root, p) {
    let succ = null;
    let curr = root;
    while (curr !== null) {
        if (curr.val > p.val) {
            succ = curr;
            curr = curr.left;
        } else {
            curr = curr.right;
        }
    }
    return succ;
};
